{
  "restricciones": [
    {
      "id": "R1",
      "cumple": true,
      "evidencia": "Arquitectura monolito modular con FastAPI (sección \"Resumen de la arquitectura\")"
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "Usa solo PostgreSQL (ARCH-04, sección \"Componentes\")"
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "No se menciona ninguna cola o broker de mensajes"
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "Correos enviados a través de /internal/mail/send (CONTRATOS, sección \"Contratos de Interfaces\")"
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "Tarea programada cada hora dentro de la misma aplicación (Decisiones de diseño, R5)"
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "No se citan servicios de terceros nuevos"
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": false,
      "evidencia": "Contrato /add define error 400 para producto repetido, pero no se menciona límite de 50 productos ni guardado de precio."
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Contrato /remove permite eliminar y error 404 cuando no existe."
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "Contrato /get devuelve lista ordenada por dateAdded."
    },
    {
      "id": "SPEC-04",
      "cubierto": false,
      "evidencia": "No se menciona la lógica de umbral configurable ni comparación de precios guardados."
    },
    {
      "id": "SPEC-05",
      "cubierto": false,
      "evidencia": "Contrato /detect y uso de /internal/mail/send, pero no se indica límite de 1 aviso por cliente-producto cada 24h."
    },
    {
      "id": "SPEC-06",
      "cubierto": false,
      "evidencia": "No se abordan clientes invitados ni deshabilitación de lista de deseos."
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": true,
  "puntaje_revision": 3,
  "justificacion": "El diseño cumple con las restricciones técnicas, pero falla en cubrir varios requisitos específicos de la especificación (límites de productos, umbral de detección y control de notificaciones)."
}

{
  "restricciones": [
    {
      "id": "R1",
      "cumple": true,
      "evidencia": "La arquitectura elegida es Monolito Modular utilizando FastAPI en Python 3.12."
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "Base de Datos (ARCH-04) ... La base de datos PostgreSQL existente es la única base de datos."
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "Sin colas ni brokers de mensajes: ARCH-03"
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "Correos internos: ARCH-03 y contrato /internal/mail/send"
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "La detección de bajas de precio se ejecuta como tarea programada cada hora dentro de la misma aplicación."
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "Sin servicios de terceros nuevos: Todas las decisiones siguen las restricciones técnicas o son necesarias por otras razones."
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": false,
      "evidencia": "El contrato /api/v1/wishlist/add no incluye guardar el precio vigente ni verificar el límite de 50 productos ni informar el motivo."
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Contrato /api/v1/wishlist/remove elimina el producto y devuelve error 404 si no estaba en la lista."
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "Contrato /api/v1/wishlist/get devuelve lista con priceSaved, priceCurrent y dateAdded, permitiendo mostrar productos ordenados por fecha de agregado."
    },
    {
      "id": "SPEC-04",
      "cubierto": false,
      "evidencia": "No se menciona comparación con precio guardado, umbral configurable del 10% ni ejecución para todos los productos de las listas de deseos."
    },
    {
      "id": "SPEC-05",
      "cubierto": false,
      "evidencia": "No se limita a un aviso cada 24h por cliente‑producto ni se incluye en el correo el precio guardado y el actual."
    },
    {
      "id": "SPEC-06",
      "cubierto": false,
      "evidencia": "Brechas de cobertura indica que SPEC-06 no se cubre explícitamente."
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": false,
  "puntaje_revision": 3,
  "justificacion": "Cumple todas las restricciones técnicas pero deja varios SPEC sin cobertura concreta y los contratos de API están incompletos, generando huecos importantes."
}
